private void backtrack(int[] nums, int start, List<List<Integer>> res) {
    if (start == nums.length) {
        List<Integer> permutation = new ArrayList<>(nums.length);
        for (int num : nums) {
            permutation.add(num);
        }
        res.add(permutation);
        return;
    }
    for (int i = start; i < nums.length; i++) {
        int temp = nums[start];
        nums[start] = nums[i];
        nums[i] = temp;
        backtrack(nums, start + 1, res);
        temp = nums[start];
        nums[start] = nums[i];
        nums[i] = temp;
    }
}

