        System.arraycopy(path, n, b, 0, n);
        String aKey = key.apply(a);
        String bKey = key.apply(b);
        graph.computeIfAbsent(aKey, k -> new java.util.ArrayList<>()).add(bKey);
        graph.computeIfAbsent(bKey, k -> new java.util.ArrayList<>()).add(aKey);
    }

    // BFS to check reachability
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.offer(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        java.util.List<String> neighbors = graph.getOrDefault(current, java.util.Collections.emptyList());
        for (String next : neighbors) {
            if (!visited.contains(next)) {
                if (next.equals(endKey)) {
                    return "can be travelled";
                }
                visited.add(next);
                queue.offer(next);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Convert coordinates to a unique string representation
    java.util.function.Function<int[], String> coordToKey = (int[] coord) -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < coord.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(coord[i]);
        }
        return sb.toString();
    };

    String startKey = coordToKey.apply(start);
    String endKey = coordToKey.apply(end);

    // If start equals end, we can trivially travel
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }

    // Build adjacency map
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();

    for (int[] p : paths) {
        // Expected format: [startCoord[0], ... startCoord[n-1], endCoord[0], ... endCoord[n-1]]
        if (p.length != 2 * n) {
            continue; // ignore malformed entries
        }
        int[] a = new int[n];
        int[] b = new int[n];
        System.arraycopy(p, 0, a, 0, n);
        System.arraycopy(p, n, b, 0, n);
        String aKey = coordToKey.apply(a);
        String bKey = coordToKey.apply(b);
        adj.computeIfAbsent(aKey, k -> new java.util.ArrayList<>()).add(bKey);
        adj.computeIfAbsent(bKey, k -> new java.util.ArrayList<>()).add(aKey);
    }

    // BFS
    java.util.Queue<String> queue = new java.util.LinkedList<>();
    java.util.Set<String> visited = new java.util.HashSet<>();

    queue.offer(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        java.util.List<String> neighbors = adj.getOrDefault(current, java.util.Collections.emptyList());
        for (String nb : neighbors) {
            if (!visited.contains(nb)) {
                if (nb.equals(endKey)) {
                    return "can be travelled";
                }
                visited.add(nb);
                queue.offer(nb);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }
    // If starting point is the same as ending point
    if (start[0] == end[0] && start[1] == end[1]) {
        return "can be travelled";
    }

    // Build adjacency list
    java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();
    for (int[] edge : paths) {
        if (edge == null || edge.length < 4) continue;
        String u = edge[0] + "#" + edge[1];
        String v = edge[2] + "#" + edge[3];
        graph.computeIfAbsent(u, k -> new java.util.ArrayList<>()).add(v);
        graph.computeIfAbsent(v, k -> new java.util.ArrayList<>()).add(u);
    }

    String startKey = start[0] + "#" + start[1];
    String endKey = end[0] + "#" + end[1];

    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();

    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        if (current.equals(endKey)) {
            return "can be travelled";
        }
        java.util.List<String> neighbors = graph.get(current);
        if (neighbors != null) {
            for (String nb : neighbors) {
                if (!visited.contains(nb)) {
                    visited.add(nb);
                    queue.add(nb);
                }
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Convert coordinates to string keys
    String startKey = java.util.Arrays.toString(start);
    String endKey = java.util.Arrays.toString(end);

    // Build adjacency map
    java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();

    // Helper to add edge
    java.util.function.BiConsumer<String, String> addEdge = (a, b) -> {
        graph.computeIfAbsent(a, k -> new java.util.ArrayList<>()).add(b);
        graph.computeIfAbsent(b, k -> new java.util.ArrayList<>()).add(a);
    };

    for (int[] path : paths) {
        if (path.length == 2) { // single indices scenario
            // If start and end are single-dimension, use them directly as strings
            String a = Integer.toString(path[0]);
            String b = Integer.toString(path[1]);
            addEdge.accept(a, b);
        } else if (path.length % 2 == 0 && path.length / 2 == start.length) {
            // Treat as split coordinates
            int half = path.length / 2;
            int[] coordA = new int[half];
            int[] coordB = new int[half];
            System.arraycopy(path, 0, coordA, 0, half);
            System.arraycopy(path, half, coordB, 0, half);
            String keyA = java.util.Arrays.toString(coordA);
            String keyB = java.util.Arrays.toString(coordB);
            addEdge.accept(keyA, keyB);
        } else {
            // Unsupported format: ignore this path
        }
    }

    // BFS from startKey to endKey
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();

    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String curr = queue.poll();
        if (curr.equals(endKey)) {
            return "can be travelled";
        }
        java.util.List<String> neighbors = graph.getOrDefault(curr, java.util.Collections.emptyList());
        for (String nb : neighbors) {
            if (!visited.contains(nb)) {
                visited.add(nb);
                queue.add(nb);
            }
        }
    }

    return "cannot be travelled";
}

public static String convertDatesToWeekdays(String date) {
    // Split the input string into month, day, and year components
    String[] parts = date.trim().split("\\s+");
    int month = Integer.parseInt(parts[0]);
    int day = Integer.parseInt(parts[1]);
    int year = Integer.parseInt(parts[2]);

    // Array of month names, 1-indexed (month 1 -> January, etc.)
    String[] monthNames = {
        "January", "February", "March", "April", "May", "June",
        "July", "August", "September", "October", "November", "December"
    };
    String monthName = monthNames[month - 1];

    // Create a LocalDate object to determine the day of the week
    java.time.LocalDate localDate = java.time.LocalDate.of(year, month, day);
    String dayName = localDate.getDayOfWeek()
                              .getDisplayName(java.time.format.TextStyle.FULL,
                                              java.util.Locale.ENGLISH);

    // Construct and return the formatted result
    return monthName + " " + day + ", " + year + " is a " + dayName;
}

public static String convertDatesToWeekdays(String date) {
