        "January", "February", "March", "April", "May", "June",
        "July", "August", "September", "October", "November", "December"
    };
    String monthName = monthNames[month - 1];

    java.util.Calendar cal = new java.util.GregorianCalendar(year, month - 1, day);
    int dayOfWeek = cal.get(java.util.Calendar.DAY_OF_WEEK);
    String weekDay;
    switch (dayOfWeek) {
        case java.util.Calendar.SUNDAY:    weekDay = "Sunday"; break;
        case java.util.Calendar.MONDAY:    weekDay = "Monday"; break;
        case java.util.Calendar.TUESDAY:   weekDay = "Tuesday"; break;
        case java.util.Calendar.WEDNESDAY: weekDay = "Wednesday"; break;
        case java.util.Calendar.THURSDAY:  weekDay = "Thursday"; break;
        case java.util.Calendar.FRIDAY:    weekDay = "Friday"; break;
        case java.util.Calendar.SATURDAY:  weekDay = "Saturday"; break;
        default: weekDay = "Unknown";
    }

    return monthName + " " + day + ", " + year + " is a " + weekDay;
}

