public boolean canArrange(int[] arr, int k) {
    // If the divisor is zero or negative, the problem is undefined
    if (k <= 0) {
        return false;
    }

    int n = arr.length;
    // The array must contain an even number of elements to form pairs
    if (n % 2 != 0) {
        return false;
    }

    int[] freq = new int[k];
    for (int num : arr) {
        // Normalise remainder to be non‑negative
        int rem = ((num % k) + k) % k;
        freq[rem]++;
    }

    // Remainder 0 elements must be in pairs
    if (freq[0] % 2 != 0) {
        return false;
    }

    // If k is even, remainder k/2 elements must also be in pairs
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) {
            return false;
        }
    }

    // For other remainders, each r must have the same count as k-r
    // We only need to iterate up to (k-1)/2 to avoid double checking
    for (int r = 1; r <= (k - 1) / 2; r++) {
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }

    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false; // cannot pair if odd length
    }
    if (k == 0) {
        return false; // division by zero undefined
    }
    int mod = Math.abs(k);
    int[] freq = new int[mod];
    for (int num : arr) {
        int r = ((num % mod) + mod) % mod; // ensure non-negative remainder
        freq[r]++;
    }
    // Remainder 0 must be even
    if (freq[0] % 2 != 0) {
        return false;
    }
    // If k is even, remainder k/2 must be even
    if (mod % 2 == 0) {
        if (freq[mod / 2] % 2 != 0) {
            return false;
        }
    }
    // For other remainders
    for (int r = 1; r < mod; r++) {
        // Avoid double checking pairs
        if (r > mod - r) {
            break;
        }
        if (freq[r] != freq[mod - r]) {
            return false;
        }
    }
    return true;
}

