    for (int num : arr) {
        int rem = ((num % k) + k) % k;  // handle negative numbers
        freq[rem]++;
    }
    // remainder 0 must pair within itself
    if (freq[0] % 2 != 0) {
        return false;
    }
    // if k even, remainder k/2 also must pair within itself
    if (k % 2 == 0) {
        int half = k / 2;
        if (freq[half] % 2 != 0) {
            return false;
        }
    }
    // for other remainders, check complement counts
    for (int r = 1; r < (k + 1) / 2; r++) {
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }
    return true;
}

