    int n = arr.length;
    int[] freq = new int[k];
    for (int num : arr) {
        int r = num % k;
        if (r < 0) r += k;
        freq[r]++;
    }
    // Check remainder 0
    if (freq[0] % 2 != 0) return false;
    // If k is even, remainder k/2 must also have even count
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) return false;
    }
    // Check other remainders
    for (int r = 1; r <= (k - 1) / 2; r++) {
        if (freq[r] != freq[k - r]) return false;
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (k <= 0) return false;                 // divisor must be positive
    int n = arr.length;
    if ((n & 1) == 1) return false;            // array length must be even
    int[] freq = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;           // positive remainder
        freq[r]++;
    }
    // remainder 0 must occur even number of times
    if (freq[0] % 2 != 0) return false;
    // if k is even, remainder k/2 must also occur even times
    if (k % 2 == 0 && freq[k / 2] % 2 != 0) return false;
    // check other remainders
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) continue;             // already handled k/2 case
        if (freq[r] != freq[k - r]) return false;
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Build adjacency list
    List<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
    for (int[] e : edges) {
        graph[e[0]].add(e[1]);
        graph[e[1]].add(e[0]);
    }

    // DFS to compute needed time for each subtree
    int dfs(int node, int parent) {
        int total = 0;
        for (int nei : graph[node]) {
            if (nei == parent) continue;
            int childTime = dfs(nei, node);
            if (childTime > 0 || hasApple[nei]) {
                total += childTime + 2; // go to child and back
            }
        }
        return total;
    }

    return dfs(0, -1);
}

int dfs(int node, int parent) {
        int total = 0;
        for (int nei : graph[node]) {
