public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    java.util.Set<Integer>[] dp = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) dp[i] = new java.util.HashSet<>();
    dp[0].add(0);
    for (int num : nums) {
        for (int k = n - 1; k >= 1; k--) {
            for (int s : dp[k - 1]) {
                dp[k].add(s + num);
            }
        }
    }
    for (int k = 1; k <= n - 1; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        if (dp[k].contains(target)) return true;
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    // dp[k] holds all possible sums of subsets of size k
    @SuppressWarnings("unchecked")
    HashSet<Integer>[] dp = new HashSet[n + 1];
    for (int i = 0; i <= n; i++) dp[i] = new HashSet<>();
    dp[0].add(0);
    for (int num : nums) {
        // iterate k from min(currentSize, n/2) down to 1
        int maxK = Math.min(n / 2, n); // we only need to consider up to n/2
        for (int k = maxK; k >= 1; k--) {
            if (dp[k - 1].isEmpty()) continue;
            for (int prevSum : dp[k - 1]) {
                int newSum = prevSum + num;
                dp[k].add(newSum);
                // check if average condition holds
                if (newSum * n == totalSum * k) {
                    return true;
                }
            }
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int totalSum = 0;
    for (int v : nums) {
        totalSum += v;
    }
    // DP: sets[k] holds all possible sums of subsets of size k
    @SuppressWarnings("unchecked")
    HashSet<Integer>[] sets = new HashSet[n + 1];
    for (int i = 0; i <= n; i++) {
        sets[i] = new HashSet<>();
    }
    sets[0].add(0);
    for (int num : nums) {
        for (int k = n - 1; k >= 0; k--) {
            if (sets[k].isEmpty()) continue;
            for (int s : sets[k]) {
                sets[k + 1].add(s + num);
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        long required = (long) totalSum * k;
        if (required % n != 0) continue;
        int target = (int) (required / n);
        if (sets[k].contains(target)) {
            return true;
        }
    }
    return false;
}

