public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    // dp0 = cost to reach step i-2, dp1 = cost to reach step i-1
    int dp0 = 0, dp1 = 0;
    for (int i = 2; i <= n; i++) {
        // cost to step onto i-1 (previous step) or i-2 and then jump to i
        int costFromPrev1 = dp1 + cost[i - 1];
        int costFromPrev2 = dp0 + cost[i - 2];
        int dp2 = Math.min(costFromPrev1, costFromPrev2);
        dp0 = dp1;
        dp1 = dp2;
    }
    return dp1;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    // dp[i] represents the minimal cost to reach step i
    int previous = cost[0];
    int current = cost[1];
    for (int i = 2; i < n; i++) {
        int next = Math.min(previous, current) + cost[i];
        previous = current;
        current = next;
    }
    return Math.min(previous, current);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    int prev2 = 0; // dp[0]
    int prev1 = 0; // dp[1]
    for (int i = 2; i <= n; i++) {
        int cur = Math.min(prev1 + cost[i - 1], prev2 + cost[i - 2]);
        prev2 = prev1;
        prev1 = cur;
    }
    return prev1;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    if (cost.length == 1) {
        return cost[0];
    }

    int prev1 = cost[0]; // dp[0]
    int prev2 = cost[1]; // dp[1]

    for (int i = 2; i < cost.length; i++) {
        int curr = cost[i] + Math.min(prev1, prev2);
        prev1 = prev2;  // shift for next iteration
        prev2 = curr;
    }

    return Math.min(prev1, prev2);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    int prev2 = 0; // dp[i-2]
    int prev1 = 0; // dp[i-1]
    for (int i = 2; i <= n; i++) {
        int payOneStep = prev1 + cost[i - 1];
        int payTwoSteps = prev2 + cost[i - 2];
        int curr = Math.min(payOneStep, payTwoSteps);
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}

