public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    if (k > n) return false;
    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int mask = total - 1;
    int code = 0;
    // Build the first code
    for (int i = 0; i < k; i++) {
        code = (code << 1) | (s.charAt(i) - '0');
    }
    seen[code] = true;
    int count = 1;
    // Slide through the string
    for (int i = k; i < n; i++) {
        code = ((code << 1) & mask) | (s.charAt(i) - '0');
        if (!seen[code]) {
            seen[code] = true;
            if (++count == total) return true;
        }
    }
    return count == total;
}

public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    if (k > n || k <= 0) return false;
    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int have = 0;
    int mask = 0;
    // build the first mask
    for (int i = 0; i < k; i++) {
        mask = (mask << 1) | (s.charAt(i) - '0');
    }
    if (!seen[mask]) {
        seen[mask] = true;
        have++;
    }
    int maskMask = total - 1; // bits set for k bits
    // slide the window
    for (int i = k; i < n; i++) {
        mask = ((mask << 1) & maskMask) | (s.charAt(i) - '0');
        if (!seen[mask]) {
            seen[mask] = true;
            if (++have == total) return true; // early exit if all found
        }
    }
    return have == total;
}

public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    // Number of distinct binary strings of length k.
    int totalCodes = 1 << k;
    // If there aren't enough substrings of length k in the string, return false early.
    if (totalCodes > n - k + 1) return false;
    boolean[] seen = new boolean[totalCodes];
    int mask = totalCodes - 1;          // mask to keep only k bits
    int current = 0;
    // Build the first window of size k.
    for (int i = 0; i < k; i++) {
        current = (current << 1) | (s.charAt(i) - '0');
    }
    seen[current] = true;
    int count = 1; // number of distinct codes seen so far
    // Slide the window through the string.
    for (int i = k; i < n; i++) {
        current = ((current << 1) & mask) | (s.charAt(i) - '0');
        if (!seen[current]) {
            seen[current] = true;
            if (++count == totalCodes) return true;
        }
    }
    return count == totalCodes;
}

public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    if (k == 0) {
