    int maskLimit = (1 << k) - 1;

    // Slide window over the rest of the string
    for (int i = k; i < n; i++) {
        mask = ((mask << 1) & maskLimit) | (s.charAt(i) - '0');
        if (!seen[mask]) {
            seen[mask] = true;
            count++;
        }
    }

    return count == total;
}

