public String makeGood(String s) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int len = sb.length();
        if (len > 0) {
            char top = sb.charAt(len - 1);
            // check if top and c are same letter but different cases
            if (top != c && Math.abs(top - c) == 32) {
                sb.deleteCharAt(len - 1);
                continue;
            }
        }
        sb.append(c);
    }
    return sb.toString();
}

