        if (n > 0) {
            char last = sb.charAt(n - 1);
            // check if last and ch are same letter ignoring case but different case
            if (Math.abs(last - ch) == 32) {
                // ASCII property: difference between uppercase and lowercase of same letter is 32
                sb.deleteCharAt(n - 1); // cancel the pair
