private void backtrack(String s, int pos, java.util.Set<String> used, int[] max) {
    if (pos == s.length()) {
        max[0] = Math.max(max[0], used.size());
        return;
    }
    for (int end = pos + 1; end <= s.length(); end++) {
        String sub = s.substring(pos, end);
        if (!used.contains(sub)) {
            used.add(sub);
            backtrack(s, end, used, max);
            used.remove(sub);
        }
    }
}

