    if (k < minSum) {
        return "";
    }
    // If the target sum equals the minimum, return all 'a's
    if (k == minSum) {
        return "a".repeat(n);
    }
    char[] result = new char[n];
    java.util.Arrays.fill(result, 'a');
    int remaining = k - minSum; // how many extra values we need to distribute
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        // Each position can contribute at most 25 extra (from 'a' to 'z')
        int add = Math.min(remaining, 25);
        result[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(result);
}

public String getSmallestString(int n, int k) {
    // The smallest possible sum is n*1 (all 'a's) and the largest is n*26 (all 'z's).
    // Assume k is within this valid range; if not, an empty string is returned.
    if (k < n || k > 26 * n) {
        return "";
    }

    int extra = k - n; // How many increments above 'a' we need to distribute.
    char[] chars = new char[n];
    for (int i = 0; i < n; i++) {
        chars[i] = 'a';
    }

    // Distribute increments starting from the rightmost character to keep the string lexicographically smallest.
    for (int i = n - 1; i >= 0 && extra > 0; i--) {
        int add = Math.min(25, extra);  // Each position can be increased by at most 25 (from 'a' to 'z').
        chars[i] = (char) ('a' + add);
        extra -= add;
    }

    return new String(chars);
}

