public static int singleNumber(int[] nums) {
    int ones = 0;
    int twos = 0;
    for (int num : nums) {
        twos |= ones & num;
        ones ^= num;
        int threes = ones & twos;
        ones &= ~threes;
        twos &= ~threes;
    }
    return ones;
}

public static int singleNumber(int[] nums) {
    int[] bits = new int[32];
    for (int num : nums) {
        for (int i = 0; i < 32; i++) {
            bits[i] += (num >> i) & 1;
        }
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        if ((bits[i] % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

