public static java.util.List<Integer> findSteppingNumbers(int low, int high) {
    java.util.List<Integer> res = new java.util.ArrayList<>();
    if (low == 0) {
        res.add(0);
    }

    java.util.Queue<Long> queue = new java.util.LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        queue.offer((long) i);
    }

    while (!queue.isEmpty()) {
        long curr = queue.poll();
        if (curr > high) continue;

        if (curr >= low) {
            res.add((int) curr);
        }

        long lastDigit = curr % 10;
        if (lastDigit > 0) {
            long next = curr * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
        if (lastDigit < 9) {
            long next = curr * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }

    java.util.Collections.sort(res);
    return res;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low == 0) {
        result.add(0);
    }
    Deque<long[]> queue = new ArrayDeque<>();
    // Initialize queue with single-digit stepping numbers (1-9)
    for (int d = 1; d <= 9; d++) {
        queue.offer(new long[]{d, d});
    }
    while (!queue.isEmpty()) {
        long[] cur = queue.poll();
        long num = cur[0];
        int lastDigit = (int) cur[1];
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add((int) num);
        }
        if (lastDigit > 0) {
            long nextNum = num * 10 + (lastDigit - 1);
            if (nextNum <= high) {
                queue.offer(new long[]{nextNum, lastDigit - 1});
            }
        }
        if (lastDigit < 9) {
            long nextNum = num * 10 + (lastDigit + 1);
            if (nextNum <= high) {
                queue.offer(new long[]{nextNum, lastDigit + 1});
            }
        }
    }
    Collections.sort(result);
    return result;
}

