public static String addThousandSeparator(int n) {
    // Handle sign
    boolean negative = n < 0;
    long value = Math.abs((long) n); // use long to avoid overflow for Integer.MIN_VALUE
    String numStr = Long.toString(value);
    StringBuilder sb = new StringBuilder();
    int count = 0;
    for (int i = numStr.length() - 1; i >= 0; i--) {
        sb.append(numStr.charAt(i));
        count++;
        if (count == 3 && i != 0) {
            sb.append('.');
            count = 0;
        }
    }
    if (negative) {
        sb.append('-');
    }
    return sb.reverse().toString();
}

public static String addThousandSeparator(int n) {
    // Handle zero separately
    if (n == 0) {
        return "0";
    }

    boolean negative = n < 0;
    // Use long to avoid overflow when n is Integer.MIN_VALUE
    long absVal = Math.abs((long) n);
    String s = Long.toString(absVal);

    int len = s.length();
    int firstGroupLen = len % 3;
    if (firstGroupLen == 0) {
        firstGroupLen = 3;
    }

    StringBuilder result = new StringBuilder();
    result.append(s, 0, firstGroupLen);

    for (int i = firstGroupLen; i < len; i += 3) {
        result.append('.');
        result.append(s, i, i + 3);
    }

    if (negative) {
        result.insert(0, '-');
    }

    return result.toString();
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }
    boolean negative = n < 0;
    long abs = n < 0 ? -(long) n : n;
    String s = Long.toString(abs);
    StringBuilder sb = new StringBuilder();
    int len = s.length();
    for (int i = 0; i < len; i++) {
        sb.append(s.charAt(len - 1 - i));
        if ((i + 1) % 3 == 0 && i != len - 1) {
            sb.append('.');
        }
    }
    sb.reverse();
    if (negative) {
        sb.insert(0, '-');
    }
    return sb.toString();
}

public static String addThousandSeparator(int n) {
    // Special case for zero
    if (n == 0) {
        return "0";
    }

    // Handle negative numbers
    boolean negative = n < 0;
    long absValue = Math.abs((long) n);

    String number = Long.toString(absValue);
    StringBuilder sb = new StringBuilder();

    int groupSize = 0;
    for (int i = number.length() - 1; i >= 0; i--) {
        sb.append(number.charAt(i));
        groupSize++;
        if (groupSize == 3 && i != 0) {
            sb.append('.');
            groupSize = 0;
        }
    }

    if (negative) {
        sb.append('-');
    }

    return sb.reverse().toString();
}

public static String addThousandSeparator(int n) {
