        return "0";
    }
    boolean negative = n < 0;
    long value = Math.abs((long) n);
    StringBuilder sb = new StringBuilder();
    while (value > 0) {
        long chunk = value % 1000;
        if (sb.length() == 0) {
            sb.insert(0, Long.toString(chunk));
        } else {
            sb.insert(0, String.format("%03d", chunk));
        }
        value /= 1000;
    }
    if (negative) {
        sb.insert(0, '-');
    }
    return sb.toString();
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    boolean[][] can = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            int sum = A[i] + A[j];
            int r = (int) Math.sqrt(sum);
            can[i][j] = r * r == sum;
        }
    }
