    java.util.Map<Long, Integer> memo = new java.util.HashMap<>();
    java.util.function.BiFunction<Integer, Integer, Integer> dfs = new java.util.function.BiFunction<Integer, Integer, Integer>() {
        @Override
        public Integer apply(Integer mask, Integer last) {
            if (mask == (1 << n) - 1) return 1;
            long key = (((long) mask) << 5) | last;
            Integer cached = memo.get(key);
            if (cached != null) return cached;
            int ways = 0;
            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) == 0 && can[last][next]) {
                    ways += apply(mask | (1 << next), next);
                }
            }
            memo.put(key, ways);
            return ways;
        }
    };
    int result = 0;
    for (int start = 0; start < n; start++) {
        result += dfs.apply(1 << start, start);
    }
    return result;
}

