public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    // Precompute perfect squares up to max(A)+max(A)
    int maxVal = 0;
    for (int v : A) if (v > maxVal) maxVal = v;
    int maxSum = maxVal * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int x = 0; x * x <= maxSum; x++) {
        isSquare[x * x] = true;
    }
    int totalMasks = 1 << n;
    long[][] dp = new long[totalMasks][n];
    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 1;
    }
    for (int mask = 1; mask < totalMasks; mask++) {
        for (int last = 0; last < n; last++) {
            long cur = dp[mask][last];
            if (cur == 0) continue;
            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) != 0) continue;
                if (isSquare[A[last] + A[next]]) {
                    dp[mask | (1 << next)][next] += cur;
                }
            }
        }
    }
    int fullMask = totalMasks - 1;
    long total = 0;
    for (int i = 0; i < n; i++) {
        total += dp[fullMask][i];
    }
    // Compute factorial for duplicate counts
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int v : A) {
        freq.put(v, freq.getOrDefault(v, 0) + 1);
    }
    long factor = 1;
    for (int count : freq.values()) {
        long f = 1;
        for (int k = 2; k <= count; k++) f *= k;
        factor *= f;
    }
    long result = total / factor;
    return (int) result;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 1;
    java.util.Arrays.sort(A);
    boolean[] used = new boolean[n];
    long[] result = new long[1];

    java.util.HashSet<Integer> memo = new java.util.HashSet<>();

    java.util.function.IntFunction<Integer> isSquare = sum -> {
        int r = (int) Math.round(Math.sqrt(sum));
        return r * r == sum ? r : -1;
    };

    java.util.function.Consumer<Integer> dfs = new java.util.function.Consumer<Integer>() {
        @Override
        public void accept(Integer depth) {
            if (depth == n) {
                result[0]++;
                return;
            }
            for (int i = 0; i < n; i++) {
                if (used[i]) continue;
                if (i > 0 && !used[i - 1] && A[i] == A[i - 1]) continue;
                if (depth > 0) {
                    int sum = A[depth - 1] + A[i];
                    int s = (int) Math.sqrt(sum);
                    if (s * s != sum) continue;
                }
                used[i] = true;
                accept(depth + 1);
                used[i] = false;
            }
        }
    };

    dfs.accept(0);
    return (int) result[0];
}

