        public long applyAsLong(long maskWithLast) {
            int mask = (int) (maskWithLast >>> 32);
            int last = (int) maskWithLast & 0xFFFFFFFFL;
            if (mask == (1 << n) - 1) return 1L;
            long &res = memo[mask][last];
            if (res != -1L) return res;
            long sum = 0L;
            for (int next = 0; next < n; next++) {
