private static List<String> build(int currLen, int totalLen) {
    if (currLen == 0) {
        java.util.List<String> base = new java.util.ArrayList<>();
        base.add("");
        return base;
    }
    if (currLen == 1) {
        java.util.List<String> base = new java.util.ArrayList<>();
        base.add("0");
        base.add("1");
        base.add("8");
        return base;
    }
    java.util.List<String> prev = build(currLen - 2, totalLen);
    java.util.List<String> result = new java.util.ArrayList<>();
    char[][] pairs = {{'0', '0'}, {'1', '1'}, {'6', '9'}, {'8', '8'}, {'9', '6'}};
    for (String s : prev) {
        for (char[] pair : pairs) {
            if (currLen == totalLen && pair[0] == '0') {
                continue;
            }
            StringBuilder sb = new StringBuilder();
            sb.append(pair[0]).append(s).append(pair[1]);
            result.add(sb.toString());
        }
    }
    return result;
}

