        if (current == original && pair[0].equals("0")) continue;
        for (String mid : prev) {
            res.add(pair[0] + mid + pair[1]);
        }
    }
    return res;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    int[] p1 = points[0];
    int[] p2 = points[1];
    int[] p3 = points[2];

    long area = (long)(p2[0] - p1[0]) * (p3[1] - p1[1])
              - (long)(p3[0] - p1[0]) * (p2[1] - p1[1]);

    return area != 0;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
