public static boolean isBoomerang(int[][] points) {
    // Ensure that we have exactly three points
    if (points == null || points.length != 3) {
        return false;
    }

    // Check that all points are distinct
    for (int i = 0; i < 3; i++) {
        for (int j = i + 1; j < 3; j++) {
            if (points[i][0] == points[j][0] && points[i][1] == points[j][1]) {
                return false; // duplicate point found
            }
        }
    }

    // Calculate the signed area (cross product) of the triangle formed by the three points
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    int cross = (x2 - x1) * (y3 - y1) - (y2 - y1) * (x3 - x1);

    // Non-zero area indicates the points are not colinear, forming a boomerang
    return cross != 0;
}

