public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    int cur = 1;
    for (int i = 0; i < n; i++) {
        result.add(cur);
        if (cur * 10 <= n) {
            cur *= 10;
        } else if (cur % 10 != 9) {
            cur++;
        } else {
            while (cur / 10 > 0 && (cur / 10) % 10 == 9) {
                cur /= 10;
            }
            cur = cur / 10 + 1;
        }
    }
    return result;
}

