private static void dfs(int curr, int n, List<Integer> result) {
    if (curr > n) return;
    result.add(curr);
    for (int i=0; i<=9; i++) {
        long next = (long) curr * 10 + i; // avoid overflow
        if (next > n) break; // If next > n, break because subsequent increments will be larger
        dfs((int) next, n, result);
    }
}

