public static int minPerfectSquareSum(int n) {
    if (n <= 0) return 0;
    int sqrtN = (int) Math.sqrt(n);
    if (sqrtN * sqrtN == n) return 1; // n is a perfect square

    // Check if sum of two squares
    for (int i = 1; i <= sqrtN; i++) {
        int rem = n - i * i;
        int sqrtRem = (int) Math.sqrt(rem);
        if (sqrtRem * sqrtRem == rem) return 2;
    }

    // Check if sum of three squares
    for (int i = 1; i <= sqrtN; i++) {
        int rem1 = n - i * i;
        if (rem1 < 0) break;
        int sqrtREM1 = (int) Math.sqrt(rem1);
        for (int j = i; j <= sqrtREM1; j++) {
            int rem2 = rem1 - j * j;
            if (rem2 < 0) break;
            int sqrtRem2 = (int) Math.sqrt(rem2);
            if (sqrtRem2 * sqrtRem2 == rem2) return 3;
        }
    }

    // By Legendre's theorem, all remaining cases require four squares
    return 4;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) return 0;
    int[] dp = new int[n + 1];
    java.util.Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            if (dp[i - square] + 1 < dp[i]) {
                dp[i] = dp[i - square] + 1;
            }
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) return 0;
    // Check if n is a perfect square
    int sqrtN = (int) Math.sqrt(n);
    if (sqrtN * sqrtN == n) return 1;
    // Check if n can be expressed as sum of two perfect squares
    for (int i = 1; i <= sqrtN; i++) {
        int remaining = n - i * i;
        int sqrtR = (int) Math.sqrt(remaining);
        if (sqrtR * sqrtR == remaining) return 2;
    }
    // Apply Legendre's 3-square theorem to determine if answer is 4
    int m = n;
    while (m % 4 == 0) {
        m /= 4;
    }
    if (m % 8 == 7) {
        return 4;
    }
    // Otherwise it's 3
    return 3;
}

