    int[] dp = new int[n + 1];
    java.util.Arrays.fill(dp, n + 1); // maximum possible value
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            if (dp[i - square] + 1 < dp[i]) {
                dp[i] = dp[i - square] + 1;
            }
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    if (s.isEmpty()) {
        return s;
    }
    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
        result.append(new StringBuilder(words[i]).reverse());
        if (i != words.length - 1) {
            result.append(" ");
        }
    }
    return result.toString();
}

public static String reverseWords(String s) {
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            result.append(word.reverse());
            word.setLength(0);
            result.append(c);
        } else {
            word.append(c);
        }
    }
    // Append the last word if any
    if (word.length() > 0) {
        result.append(word.reverse());
    }
    return result.toString();
}

public static String reverseWords(String s) {
    StringBuilder result = new StringBuilder();
    int n = s.length();
    int i = 0;
    while (i < n) {
        if (s.charAt(i) == ' ') {
            result.append(' ');
            i++;
        } else {
            int j = i;
            while (j < n && s.charAt(j) != ' ') {
                j++;
            }
            for (int k = j - 1; k >= i; k--) {
                result.append(s.charAt(k));
            }
            i = j;
        }
    }
    return result.toString();
}

